12	  <style>
13	    *,
14	    *::before,
15	    *::after {
16	      box-sizing: border-box;
17	      margin: 0;
18	      padding: 0;
19	    }
20	    :root {
21	      color-scheme: light dark;
22	      --bg: #fff;
23	      --text: #374151;
24	      --fg: #2563eb;
25	      --shadow: rgba(0, 0, 0, 0.1);
26	      --kbd-bg: rgba(0, 0, 0, 0.1);
27	      --drop: drop-shadow(0 4px 12px var(--shadow));
28	    }
29	    [data-color="red"] { --fg: #dc2626; }
30	    /* Dark enough to keep 3:1 against --bg at the resting 0.85 opacity */
31	    [data-color="green"] { --fg: #15803d; }
32	    [data-color="amber"] { --fg: #b45309; }
33	    [data-color="violet"] { --fg: #7c3aed; }
34	    [data-color="cyan"] { --fg: #0e7490; }
35	    @media (prefers-color-scheme: dark) {
36	      :root {
37	        --bg: #111;
38	        --text: #d1d5db;
39	        --fg: #93c5fd;
40	        --shadow: rgba(0, 0, 0, 0.6);
41	        --kbd-bg: rgba(255, 255, 255, 0.15);
42	      }
43	      [data-color="red"] { --fg: #fca5a5; }
44	      [data-color="green"] { --fg: #86efac; }
45	      [data-color="amber"] { --fg: #fcd34d; }
46	      [data-color="violet"] { --fg: #c4b5fd; }
47	      [data-color="cyan"] { --fg: #67e8f9; }
48	    }
49	    @media (prefers-contrast: more) {
50	      :root {
51	        --shadow: rgba(0, 0, 0, 0.9);
52	        --drop: drop-shadow(0 2px 8px var(--shadow));
53	      }
54	      .circle svg {
55	        opacity: 1;
56	      }
57	    }
58	    @media (forced-colors: active) {
59	      svg circle {
60	        stroke: CanvasText;
61	        stroke-width: 2;
62	      }
63	    }
64	    body {
65	      min-height: 100vh;
66	      min-height: 100dvh;
67	      display: grid;
68	      place-items: center;
69	      padding: 1rem;
70	      background: var(--bg);
71	      color: var(--text);
72	      font-family: system-ui, -apple-system, sans-serif;
73	    }
74	    main {
75	      width: 100%;
76	      display: flex;
77	      flex-direction: column;
78	      align-items: center;
79	      text-align: center;
80	    }
81	    .circle {
82	      display: block;
83	      width: min(360px, 100%, 60vh);
84	      aspect-ratio: 1;
85	      border: 0;
86	      border-radius: 50%;
87	      background: none;
88	      color: var(--fg);
89	      cursor: pointer;
90	      touch-action: manipulation;
91	      -webkit-tap-highlight-color: transparent;
92	      /* Shift+click and double-click would otherwise select the text below */
93	      -webkit-user-select: none;
94	      user-select: none;
95	      -webkit-touch-callout: none;
96	      transition: color 0.4s ease;
97	      min-height: 48px;
98	      min-width: 48px;
99	    }
100	    .no-transition,
101	    .no-transition svg {
102	      transition: none !important;
103	    }
104	    .circle:focus-visible {
105	      outline: 3px solid currentColor;
106	      outline-offset: 12px;
107	    }
108	    svg {
109	      display: block;
110	      width: 100%;
111	      height: 100%;
112	      overflow: visible;
113	      opacity: 0.85;
114	      filter: var(--drop);
115	      transition: opacity 0.3s ease;
116	    }
117	    .circle:active svg,
118	    .circle:focus-visible svg {
119	      opacity: 1;
120	    }
121	    @keyframes pulse {
122	      0% {
123	        filter: var(--drop) drop-shadow(0 0 16px currentColor);
124	      }
125	      100% {
126	        filter: var(--drop) drop-shadow(0 0 0 transparent);
127	      }
128	    }
129	    @media (hover: hover) {
130	      .circle:hover svg {
131	        opacity: 1;
132	      }
133	    }
134	    @media (prefers-reduced-motion: no-preference) {
135	      svg {
136	        transition:
137	          transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1),
138	          opacity 0.3s ease;
139	      }
140	      .circle:focus-visible svg {
141	        transform: scale(1.05);
142	      }
143	      .circle:active svg {
144	        transform: scale(0.97);
145	      }
146	      .circle.color-changed svg {
147	        animation: pulse 0.5s ease-out;
148	      }
149	    }
150	    @media (hover: hover) and (prefers-reduced-motion: no-preference) {
151	      .circle:hover:not(:active) svg {
152	        transform: scale(1.05);
153	      }
154	    }
155	    .visually-hidden {
156	      position: absolute;
157	      width: 1px;
158	      height: 1px;
159	      overflow: hidden;
160	      clip-path: inset(50%);
161	      white-space: nowrap;
162	    }
163	    .status {
164	      margin-top: 2rem;
165	      font-weight: 600;
166	    }
167	    .hint {
168	      margin-top: 0.25rem;
169	      font-size: 0.875rem;
170	      line-height: 1.75;
171	      text-wrap: balance;
172	    }
173	    .help-button {
174	      margin-left: 0.5rem;
175	      display: inline-block;
176	      width: 1.5rem;
177	      height: 1.5rem;
178	      border-radius: 50%;
179	      background: var(--kbd-bg);
180	      border: 1px solid var(--text);
181	      color: var(--text);
182	      cursor: pointer;
183	      font: inherit;
184	      font-size: 0.75rem;
185	      font-weight: bold;
186	      line-height: 1;
187	      text-align: center;
188	      vertical-align: middle;
189	      touch-action: manipulation;
190	      transition: background-color 0.2s ease, color 0.2s ease;
191	    }
192	    .help-button:focus-visible {
193	      outline: 2px solid currentColor;
194	      outline-offset: 2px;
195	    }
196	    @media (hover: hover) {
197	      /* Not currentColor: it would resolve to the hover color and hide the "?" */
198	      .help-button:hover {
199	        background: var(--text);
200	        color: var(--bg);
201	      }
202	    }
203	    .keys {
204	      display: none;
205	    }
206	    .keys.visible {
207	      display: inline;
208	    }
209	    @media (hover: none) and (pointer: coarse) {
210	      .hint .keys {
211	        display: none !important;
212	      }
213	      .help-button {
214	        display: none;
215	      }
216	    }
217	    kbd {
218	      display: inline-block;
219	      padding: 0.125rem 0.375rem;
220	      background: var(--kbd-bg);
221	      border: 1px solid transparent;
222	      border-radius: 0.25rem;
223	      font-family: monospace;
224	      font-size: 0.75em;
225	      line-height: 1.2;
226	    }
227	  </style>
228	</head>
229	<body>
230	  <main>
231	    <h1 class="visually-hidden">Animated Circle</h1>
232	    <button type="button" class="circle no-transition" aria-label="Change circle color" aria-describedby="status hint">
233	      <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg">
234	        <circle cx="50" cy="50" r="50" fill="currentColor" stroke="none"/>
235	      </svg>
236	    </button>
237	    <p class="status" id="status" role="status">Blue</p>
238	    <p class="hint"><span id="hint"><span class="verb">Click</span> to cycle • <span class="double-verb">Double-click</span> or hold to reset<span class="keys" id="keys"> • <kbd>Shift</kbd>+click reverse • <kbd>↑↓←→</kbd> navigate • <kbd>Home</kbd>/<kbd>End</kbd> jump</span></span> <button type="button" class="help-button" aria-label="Keyboard shortcuts" aria-expanded="false" aria-controls="keys"><span aria-hidden="true">?</span></button></p>
239	    <noscript><p class="hint">JavaScript is required to change the color.</p></noscript>
240	  </main>
241	  <script>
242	    const config = {
243	      colors: ['blue', 'red', 'green', 'amber', 'violet', 'cyan'],
244	      storageKey: 'circle-color',
245	      hapticDuration: 50,
246	      longPressDuration: 500,
247	      keySteps: { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 },
248	    };
249	
250	    const DOM = {
251	      button: document.querySelector('.circle'),
252	      status: document.querySelector('.status'),
253	      helpButton: document.querySelector('.help-button'),
254	      keyHint: document.querySelector('.keys'),
255	      verbSpan: document.querySelector('.hint .verb'),
256	      doubleVerbSpan: document.querySelector('.hint .double-verb'),
257	    };
258	
259	    const state = {
260	      index: 0,
261	      shiftHeld: false,
262	      hoverCapable: true,
263	      reducedMotion: matchMedia('(prefers-reduced-motion: reduce)'),
264	      hoverQuery: matchMedia('(hover: none)'),
265	      longPressTimer: null,
266	      longPressed: false,
267	    };
268	
269	    function loadColor() {
270	      try {
271	        return localStorage.getItem(config.storageKey);
272	      } catch {
273	        return null;
274	      }
275	    }
276	
277	    function saveColor(color) {
278	      try {
279	        localStorage.setItem(config.storageKey, color);
280	      } catch {}
281	    }
282	
283	    function applyColor() {
284	      const color = config.colors[state.index];
285	      DOM.button.dataset.color = color === 'blue' ? '' : color;
286	      DOM.status.textContent = color[0].toUpperCase() + color.slice(1);
287	    }
288	
289	    function syncFromStorage(color = loadColor()) {
290	      const index = config.colors.indexOf(color);
291	      state.index = index === -1 ? 0 : index;
292	      applyColor();
293	    }
294	
295	    function setIndex(next, { haptic = false } = {}) {
296	      if (next === state.index) return;
297	      state.index = next;
298	      applyColor();
299	      saveColor(config.colors[state.index]);
300	
301	      if (haptic && navigator.vibrate) navigator.vibrate(config.hapticDuration);
302	
303	      if (state.reducedMotion.matches) return;
304	      DOM.button.classList.remove('color-changed');
305	      void DOM.button.offsetWidth;
306	      DOM.button.classList.add('color-changed');
307	    }
308	
309	    function changeColor(step) {
310	      setIndex((state.index + step + config.colors.length) % config.colors.length, { haptic: true });
311	    }
312	
313	    function updateDeviceVerbs() {
314	      state.hoverCapable = !state.hoverQuery.matches;
315	      DOM.verbSpan.textContent = state.hoverCapable ? 'Click' : 'Tap';
316	      DOM.doubleVerbSpan.textContent = state.hoverCapable ? 'Double-click' : 'Double-tap';
317	    }
318	
319	    function toggleKeyHintVisibility() {
320	      const expanded = DOM.keyHint.classList.toggle('visible');
321	      DOM.helpButton.setAttribute('aria-expanded', expanded);
322	    }
323	
324	    function syncKeyHint() {
325	      DOM.keyHint.classList.toggle('visible', state.hoverCapable);
326	      DOM.helpButton.setAttribute('aria-expanded', state.hoverCapable);
327	    }
328	
329	    function handleKeyDown(event) {
330	      if (event.key === 'Enter' || event.key === ' ') {
331	        if (!event.repeat) state.shiftHeld = event.shiftKey;
332	        if (event.key === 'Enter' && event.repeat) event.preventDefault();
333	        return;
334	      }
335	
336	      if (event.altKey || event.ctrlKey || event.metaKey) return;
337	
338	      if (event.key in config.keySteps) {
339	        event.preventDefault();
340	        changeColor(config.keySteps[event.key]);
341	      } else if (event.key === 'Home') {
342	        event.preventDefault();
343	        setIndex(0, { haptic: true });
344	      } else if (event.key === 'End') {
345	        event.preventDefault();
346	        setIndex(config.colors.length - 1, { haptic: true });
347	      }
348	    }
349	
350	    // Initialize
351	    syncFromStorage();
352	
353	    requestAnimationFrame(() => requestAnimationFrame(() => {
354	      DOM.button.classList.remove('no-transition');
355	    }));
356	
357	    updateDeviceVerbs();
358	    syncKeyHint();
359	    // e.g. a tablet gaining or losing a trackpad/keyboard
360	    state.hoverQuery.addEventListener('change', () => {
361	      updateDeviceVerbs();
362	      syncKeyHint();
363	    });
364	
365	    // Event listeners
366	    function clearLongPressTimer() {
367	      if (state.longPressTimer) clearTimeout(state.longPressTimer);
368	      state.longPressTimer = null;
369	    }
370	
371	    DOM.button.addEventListener('keydown', handleKeyDown);
372	    DOM.button.addEventListener('keyup', (event) => {
373	      if (event.key === ' ') state.shiftHeld = event.shiftKey;
374	    });
375	    DOM.button.addEventListener('blur', () => {
376	      state.shiftHeld = false;
377	      clearLongPressTimer();
378	    });
379	    DOM.button.addEventListener('pointerdown', (event) => {
380	      clearLongPressTimer();
381	      state.longPressed = false;
382	      if (!event.isPrimary || event.button !== 0) return;
383	      state.longPressTimer = setTimeout(() => {
384	        state.longPressTimer = null;
385	        state.longPressed = true;
386	        setIndex(0, { haptic: true });
387	      }, config.longPressDuration);
388	    });
389	    DOM.button.addEventListener('pointerup', clearLongPressTimer);
390	    DOM.button.addEventListener('pointercancel', clearLongPressTimer);
391	    DOM.button.addEventListener('pointerleave', clearLongPressTimer);
392	    DOM.button.addEventListener('click', (event) => {
393	      clearLongPressTimer();
394	      // Releasing a long press still fires a click, which would undo the reset.
395	      // Keyboard clicks (detail 0) are never part of a long press.
396	      const afterLongPress = state.longPressed && event.detail !== 0;
397	      state.longPressed = false;
398	      if (afterLongPress || event.detail > 1) return;
399	      changeColor(event.shiftKey || state.shiftHeld ? -1 : 1);
400	      state.shiftHeld = false;
401	    });
402	    DOM.button.addEventListener('dblclick', (event) => {
403	      event.preventDefault();
404	      setIndex(0);
405	    });
406	    DOM.button.addEventListener('animationend', () => {
407	      DOM.button.classList.remove('color-changed');
408	    });
409	
410	    DOM.helpButton.addEventListener('click', toggleKeyHintVisibility);
411	
412	    addEventListener('storage', (event) => {
413	      if (event.key !== config.storageKey && event.key !== null) return;
414	      syncFromStorage(event.newValue);
415	    });
416	    // Storage events are not delivered while the page sits in the bfcache
417	    addEventListener('pageshow', (event) => {
418	      if (event.persisted) syncFromStorage();
419	    });
420	  </script>
421	</body>
422	</html>
